import { useState } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import { Fuel, Loader2 } from "lucide-react";
import { toast } from "sonner";

import { useAuth } from "@/lib/auth-store";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent } from "@/components/ui/card";

export default function LoginPage() {
  const login = useAuth((s) => s.login);
  const user = useAuth((s) => s.user);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const from = (location.state as { from?: { pathname?: string } } | null)?.from?.pathname ?? "/";

  if (user) {
    navigate(from === "/login" ? "/dashboard" : from, { replace: true });
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSubmitting(true);
    try {
      await login(username.trim(), password);
      toast.success("Welcome back");
      navigate("/dashboard", { replace: true });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Login failed");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="grid min-h-screen lg:grid-cols-2">
      <div className="relative hidden lg:flex flex-col justify-between overflow-hidden bg-gradient-to-br from-primary/90 via-primary/60 to-sky-500/60 p-12 text-primary-foreground">
        <div className="flex items-center gap-3 text-lg font-semibold">
          <div className="flex h-9 w-9 items-center justify-center rounded-md bg-white/20">
            <Fuel className="h-5 w-5" />
          </div>
          MKR Gas
        </div>
        <div className="space-y-3">
          <div className="text-3xl font-semibold tracking-tight">Run your station with confidence.</div>
          <p className="max-w-md text-base text-primary-foreground/90">
            Daily margin tracking, schedules, end-of-day reporting and reports built around the
            way you already run the business in your spreadsheet -- just faster.
          </p>
        </div>
        <div className="text-xs text-primary-foreground/70">© {new Date().getFullYear()} MKR Gas</div>
      </div>

      <div className="flex items-center justify-center p-6">
        <Card className="w-full max-w-md">
          <CardContent className="space-y-6 p-8">
            <div className="space-y-1">
              <div className="text-2xl font-semibold tracking-tight">Sign in</div>
              <p className="text-sm text-muted-foreground">
                Enter your MKR Gas credentials to continue.
              </p>
            </div>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-1.5">
                <Label htmlFor="username">Username</Label>
                <Input
                  id="username"
                  autoComplete="username"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  required
                  autoFocus
                />
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="password">Password</Label>
                <Input
                  id="password"
                  type="password"
                  autoComplete="current-password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
              </div>
              <Button type="submit" className="w-full" disabled={submitting} size="lg">
                {submitting ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
                Sign in
              </Button>
            </form>
            <p className="text-xs text-muted-foreground">
              Lost your password? Ask an admin to reset it from the Employees screen.
            </p>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}
