export default function SettingsPage() {
  const isAdmin = useAuth((s) => s.user?.role === "admin");
  return (
    <div className="space-y-8">
      <header>
        <h1 className="text-3xl font-semibold tracking-tight">Settings</h1>
        <p className="text-sm text-muted-foreground">
          Configure store, fuel grades, and the Canadian tax constants used by the margin engine.
        </p>
      </header>

      <Tabs defaultValue="taxes">
        <TabsList>
          <TabsTrigger value="taxes">Tax constants</TabsTrigger>
          <TabsTrigger value="grades">Fuel grades</TabsTrigger>
          <TabsTrigger value="store">Store</TabsTrigger>
          {isAdmin ? <TabsTrigger value="import">Import</TabsTrigger> : null}
          {isAdmin ? <TabsTrigger value="danger">Danger zone</TabsTrigger> : null}
        </TabsList>
        <TabsContent value="taxes">
          <TaxConstantsEditor />
        </TabsContent>
        <TabsContent value="grades">
          <FuelGradesEditor />
        </TabsContent>
        <TabsContent value="store">
          <StoreEditor />
        </TabsContent>
        {isAdmin ? (
          <TabsContent value="import">
            <ExcelImportPage />
          </TabsContent>
        ) : null}
        {isAdmin ? (
          <TabsContent value="danger">
            <DangerZone />
          </TabsContent>
        ) : null}
      </Tabs>
    </div>
  );
}

function TaxConstantsEditor() {
  const qc = useQueryClient();
  const q = useQuery({
    queryKey: ["config", "taxes"],
    queryFn: () => api.readData<TaxConstants>("config/taxes.json"),
  });
  const [state, setState] = useState<TaxConstants>(DEFAULT_TAXES);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (q.data?.exists && q.data.data) setState(q.data.data);
  }, [q.data?.exists, q.data?.data]);

  async function save() {
    setSaving(true);
    try {
      await api.writeData("config/taxes.json", state, q.data?.sha ?? null, "config: taxes");
      toast.success("Tax constants saved");
      qc.invalidateQueries({ queryKey: ["config", "taxes"] });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to save");
    } finally {
      setSaving(false);
    }
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>Tax constants (mirrors Excel cells Q10..Q17)</CardTitle>
        <CardDescription>
          Per-liter consumption taxes and the GST/PST/HST percentages. When HST is &gt; 0 it
          replaces GST+PST in the net-sell-price calculation.
        </CardDescription>
      </CardHeader>
      <CardContent className="grid gap-4 md:grid-cols-3">
        <Field
          label="Region label"
          value={state.region ?? ""}
          onChange={(v) => setState({ ...state, region: v })}
          type="text"
        />
        <Field
          label="FET $/L"
          value={state.fetPerL}
          onChange={(v) => setState({ ...state, fetPerL: v })}
        />
        <Field
          label="PFT $/L"
          value={state.pftPerL}
          onChange={(v) => setState({ ...state, pftPerL: v })}
        />
        <Field
          label="Carbon $/L"
          value={state.carbonPerL}
          onChange={(v) => setState({ ...state, carbonPerL: v })}
        />
        <Field
          label="Urban surcharge $/L"
          value={state.urbanPerL}
          onChange={(v) => setState({ ...state, urbanPerL: v })}
        />
        <Field
          label="Rebate $/L (added back)"
          value={state.rebatePerL}
          onChange={(v) => setState({ ...state, rebatePerL: v })}
        />
        <Field
          label="GST %"
          value={state.gstPct}
          onChange={(v) => setState({ ...state, gstPct: v })}
        />
        <Field
          label="PST %"
          value={state.pstPct}
          onChange={(v) => setState({ ...state, pstPct: v })}
        />
        <Field
          label="HST % (replaces GST+PST when &gt; 0)"
          value={state.hstPct}
          onChange={(v) => setState({ ...state, hstPct: v })}
        />
        <div className="md:col-span-3 flex justify-end">
          <Button onClick={save} disabled={saving}>
            {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
            Save tax constants
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

function FuelGradesEditor() {
  const qc = useQueryClient();
  const q = useQuery({
    queryKey: ["config", "fuel_grades"],
    queryFn: () => api.readData<FuelGradesConfig>("config/fuel_grades.json"),
  });
  const [state, setState] = useState<FuelGradesConfig>(DEFAULT_GRADES);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (q.data?.exists && q.data.data) setState(q.data.data);
  }, [q.data?.exists, q.data?.data]);

  async function save() {
    setSaving(true);
    try {
      await api.writeData(
        "config/fuel_grades.json",
        state,
        q.data?.sha ?? null,
        "config: fuel grades",
      );
      toast.success("Fuel grades saved");
      qc.invalidateQueries({ queryKey: ["config", "fuel_grades"] });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to save");
    } finally {
      setSaving(false);
    }
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>Fuel grades</CardTitle>
        <CardDescription>
          Add or remove grades. Opening inventory + opening rolling-average cost seed the math
          engine for the first day.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {state.grades.map((g, i) => (
          <div
            key={g.id}
            className="grid grid-cols-2 gap-3 rounded-md border bg-card/40 p-4 md:grid-cols-[1fr_1.2fr_1fr_1fr_1fr_auto] md:items-end"
          >
            <Field
              label="ID (slug)"
              value={g.id}
              onChange={(v) =>
                setState({
                  ...state,
                  grades: state.grades.map((gg, j) => (i === j ? { ...gg, id: v } : gg)),
                })
              }
              type="text"
            />
            <Field
              label="Display label"
              value={g.label}
              onChange={(v) =>
                setState({
                  ...state,
                  grades: state.grades.map((gg, j) => (i === j ? { ...gg, label: v } : gg)),
                })
              }
              type="text"
            />
            <Field
              label="Tank capacity (L)"
              value={g.tankCapacityL ?? 0}
              onChange={(v) =>
                setState({
                  ...state,
                  grades: state.grades.map((gg, j) =>
                    i === j ? { ...gg, tankCapacityL: v } : gg,
                  ),
                })
              }
            />
            <Field
              label="Opening inv (L)"
              value={state.openingInventoryL[g.id] ?? 0}
              onChange={(v) =>
                setState({
                  ...state,
                  openingInventoryL: { ...state.openingInventoryL, [g.id]: v },
                })
              }
            />
            <Field
              label="Opening avg $/L"
              value={state.openingRollingAvgCost?.[g.id] ?? 0}
              onChange={(v) =>
                setState({
                  ...state,
                  openingRollingAvgCost: { ...(state.openingRollingAvgCost ?? {}), [g.id]: v },
                })
              }
              step={0.0001}
            />
            <Button
              variant="ghost"
              size="icon"
              onClick={() =>
                setState({
                  ...state,
                  grades: state.grades.filter((_, j) => j !== i),
                })
              }
              aria-label="Remove grade"
            >
              <Trash2 className="h-4 w-4" />
            </Button>
          </div>
        ))}
        <Button
          variant="outline"
          onClick={() =>
            setState({
              ...state,
              grades: [
                ...state.grades,
                {
                  id: `grade${state.grades.length + 1}`,
                  label: "NEW GRADE",
                  tankCapacityL: 0,
                },
              ],
            })
          }
        >
          <Plus className="h-4 w-4" /> Add grade
        </Button>
        <div className="flex justify-end">
          <Button onClick={save} disabled={saving}>
            {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
            Save grades
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

