function DangerZone() {
  const qc = useQueryClient();
  const [openScope, setOpenScope] = useState<"transactional" | "everything" | null>(null);
  const [phrase, setPhrase] = useState("");
  const [working, setWorking] = useState(false);

  const expected =
    openScope === "everything" ? "FACTORY RESET" : openScope === "transactional" ? "RESET TRANSACTIONAL" : "";

  async function execute() {
    if (!openScope) return;
    setWorking(true);
    try {
      const result = await api.resetData(openScope, phrase.trim());
      toast.success(
        `${openScope === "everything" ? "Factory reset" : "Transactional reset"} complete -- removed ${result.deletedCount} file(s).`,
      );
      qc.clear();
      setOpenScope(null);
      setPhrase("");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Reset failed");
    } finally {
      setWorking(false);
    }
  }

  return (
    <Card className="border-destructive/40">
      <CardHeader>
        <CardTitle className="flex items-center gap-2 text-destructive">
          <AlertTriangle className="h-5 w-5" /> Danger zone
        </CardTitle>
        <CardDescription>
          Destructive operations. Every reset is logged in the audit log and produces a single git
          commit in the data repo, so changes are auditable and reversible via git history if needed.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="rounded-md border border-amber-300/40 bg-amber-50/30 p-4 dark:border-amber-900/40 dark:bg-amber-950/20">
          <div className="mb-2 flex items-center gap-2 font-medium">
            <AlertTriangle className="h-4 w-4 text-amber-600 dark:text-amber-400" />
            Reset transactional data
          </div>
          <p className="mb-3 text-sm text-muted-foreground">
            Deletes every <code>sales/</code>, <code>derived/</code>, <code>fuel_deliveries/</code>,{" "}
            <code>gas_prices/</code>, <code>expenses/</code>, <code>schedules/</code>, and{" "}
            <code>inventory/</code> file. Keeps configuration, users, vendors, and the audit log.
          </p>
          <Button variant="outline" onClick={() => setOpenScope("transactional")}>
            Reset transactional data
          </Button>
        </div>

        <div className="rounded-md border border-destructive/40 bg-destructive/5 p-4">
          <div className="mb-2 flex items-center gap-2 font-medium text-destructive">
            <AlertTriangle className="h-4 w-4" />
            Factory reset (everything)
          </div>
          <p className="mb-3 text-sm text-muted-foreground">
            Deletes all transactional data <em>plus</em> tax constants, fuel grades, store config,
            and vendors. Rebuilds <code>users.json</code> with only your own admin account so you
            don&apos;t get locked out. The audit log is preserved.
          </p>
          <Button variant="destructive" onClick={() => setOpenScope("everything")}>
            Factory reset
          </Button>
        </div>
      </CardContent>

      <Dialog open={openScope !== null} onOpenChange={(open) => (!open ? setOpenScope(null) : null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-destructive">
              <AlertTriangle className="h-5 w-5" />
              Confirm {openScope === "everything" ? "factory reset" : "transactional reset"}
            </DialogTitle>
            <DialogDescription>
              This cannot be undone from the app (the data repo&apos;s git history will retain the
              old commits, but you would need to manually revert there). Type the phrase below
              exactly to proceed.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-3">
            <div className="rounded-md bg-muted px-3 py-2 font-mono text-sm">{expected}</div>
            <Input
              autoFocus
              value={phrase}
              onChange={(e) => setPhrase(e.target.value)}
              placeholder="Type the phrase exactly"
              disabled={working}
            />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setOpenScope(null)} disabled={working}>
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={execute}
              disabled={working || phrase.trim() !== expected}
            >
              {working ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
              I understand, proceed
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </Card>
  );
}

function Field({
  label,
  value,
  onChange,
  type = "number",
  step,
}: {
  label: string;
  value: number | string;
  onChange: (v: never) => void;
  type?: "number" | "text";
  step?: number;
}) {
  return (
    <div className="space-y-1.5">
      <Label className="text-xs text-muted-foreground">{label}</Label>
      <Input
        type={type}
        step={step ?? (type === "number" ? 0.01 : undefined)}
        inputMode={type === "number" ? "decimal" : undefined}
        value={value as string | number}
        onChange={(e) => {
          if (type === "number") {
            (onChange as (v: number) => void)(parseFloat(e.target.value) || 0);
          } else {
            (onChange as (v: string) => void)(e.target.value);
          }
        }}
      />
    </div>
  );
}
