import { useQueries, useQuery } from "@tanstack/react-query";
import { useMemo } from "react";
import {
  ArrowDownRight,
  ArrowUpRight,
  Droplets,
  Fuel,
  Loader2,
  TrendingUp,
  Wallet,
} from "lucide-react";

import { api } from "@/lib/api";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { EChart } from "@/charts/EChart";
import { chartGrid, colorForGrade, tooltipStyle } from "@/charts/theme";
import { formatCAD, formatLiters, formatPerLiter, isoDate, isoMonth } from "@/lib/utils";
import type {
  DerivedMarginFile,
  FuelGradesConfig,
  SalesFile,
} from "@/lib/types";
import { useAuth } from "@/lib/auth-store";

function lastNDates(n: number, anchor: Date = new Date()): string[] {
  const out: string[] = [];
  const a = new Date(anchor);
  for (let i = n - 1; i >= 0; i--) {
    const d = new Date(a);
    d.setDate(a.getDate() - i);
    out.push(isoDate(d));
  }
  return out;
}

export default function DashboardPage() {
  const user = useAuth((s) => s.user)!;
  const today = isoDate();
  const month = isoMonth();
  const dates = useMemo(() => lastNDates(30), []);

  const gradesQ = useQuery({
    queryKey: ["config", "fuel_grades"],
    queryFn: () => api.readData<FuelGradesConfig>("config/fuel_grades.json"),
  });
  const todaySalesQ = useQuery({
    queryKey: ["sales", today],
    queryFn: () => api.readData<SalesFile>(`sales/${today}.json`),
  });
  const todayMarginQ = useQuery({
    queryKey: ["margin", today],
    queryFn: () => api.readData<DerivedMarginFile>(`derived/margin/${today}.json`),
  });
  const marginQs = useQueries({
    queries: dates.map((d) => ({
      queryKey: ["margin", d],
      queryFn: () => api.readData<DerivedMarginFile>(`derived/margin/${d}.json`),
    })),
  });
  const salesQs = useQueries({
    queries: dates.map((d) => ({
      queryKey: ["sales", d],
      queryFn: () => api.readData<SalesFile>(`sales/${d}.json`),
    })),
  });
  const loading =
    gradesQ.isLoading ||
    todaySalesQ.isLoading ||
    todayMarginQ.isLoading ||
    marginQs.some((q) => q.isLoading) ||
    salesQs.some((q) => q.isLoading);

  const grades = gradesQ.data?.data?.grades ?? [];

  const dailyMargins = dates.map((date, i) => ({
    date,
    margin: marginQs[i].data?.data,
    sales: salesQs[i].data?.data,
  }));

  const todayMargin = todayMarginQ.data?.data;
  const todaySales = todaySalesQ.data?.data;

  const todayGallonsSold = todayMargin?.rows.reduce((s, r) => s + r.bullochVolumeL, 0) ?? 0;
  const todayGrossProfit = todayMargin?.rows.reduce((s, r) => s + r.grossProfit, 0) ?? 0;
  const todayFuelRevenue =
    todaySales?.fuel.reduce((s, f) => s + f.bullochSalesCAD, 0) ??
    todayMargin?.rows.reduce((s, r) => s + r.bullochSalesCAD, 0) ??
    0;

  const mtdGrossProfit = dailyMargins.reduce((s, d) => {
    if (!d.date.startsWith(month)) return s;
    return s + (d.margin?.rows.reduce((ss, r) => ss + r.grossProfit, 0) ?? 0);
  }, 0);

  const mtdLitersSold = dailyMargins.reduce((s, d) => {
    if (!d.date.startsWith(month)) return s;
    return s + (d.margin?.rows.reduce((ss, r) => ss + r.bullochVolumeL, 0) ?? 0);
  }, 0);

  const rollingWeightedMargin = mtdLitersSold > 0 ? mtdGrossProfit / mtdLitersSold : 0;

  const yesterday = dailyMargins[dailyMargins.length - 2];
  const yesterdayGP = yesterday?.margin?.rows.reduce((s, r) => s + r.grossProfit, 0) ?? 0;
  const dayChange = yesterdayGP > 0 ? ((todayGrossProfit - yesterdayGP) / yesterdayGP) * 100 : 0;

  const marginLineOption = {
    grid: chartGrid,
    tooltip: tooltipStyle,
    xAxis: { type: "category", data: dates, axisLine: { lineStyle: { color: "#475569" } } },
    yAxis: {
      type: "value",
      axisLabel: { formatter: (v: number) => `$${v.toFixed(2)}/L` },
      splitLine: { lineStyle: { color: "rgba(148,163,184,0.15)" } },
    },
    series: grades.map((g) => ({
      name: g.label,
      type: "line",
      smooth: true,
      showSymbol: false,
      lineStyle: { width: 2.2 },
      itemStyle: { color: colorForGrade(g.id, g.color) },
      data: dailyMargins.map((d) => {
        const row = d.margin?.rows.find((r) => r.gradeId === g.id);
        return row?.hasSales ? Number(row.associateMargin.toFixed(4)) : null;
      }),
    })),
    legend: { textStyle: { color: "#94a3b8" }, top: 4 },
  };

  const grossProfitBarOption = {
    grid: chartGrid,
    tooltip: tooltipStyle,
    xAxis: { type: "category", data: dates.map((d) => d.slice(5)) },
    yAxis: {
      type: "value",
      axisLabel: { formatter: (v: number) => `$${v.toLocaleString("en-CA")}` },
      splitLine: { lineStyle: { color: "rgba(148,163,184,0.15)" } },
    },
    series: [
      {
        type: "bar",
        name: "Gross profit",
        itemStyle: { color: "#14b8a6", borderRadius: [4, 4, 0, 0] },
        data: dailyMargins.map(
          (d) => Number((d.margin?.rows.reduce((s, r) => s + r.grossProfit, 0) ?? 0).toFixed(2)),
        ),
      },
    ],
  };

  const fuelMixDonutOption = {
    tooltip: { ...tooltipStyle, trigger: "item" },
    legend: { bottom: 0, textStyle: { color: "#94a3b8" } },
    series: [
      {
        type: "pie",
        radius: ["55%", "78%"],
        avoidLabelOverlap: true,
        itemStyle: { borderColor: "transparent", borderWidth: 2 },
        label: { show: false },
        data: grades.map((g) => ({
          name: g.label,
          value: dailyMargins.reduce((s, d) => {
            const row = d.margin?.rows.find((r) => r.gradeId === g.id);
            return s + (row?.bullochVolumeL ?? 0);
          }, 0),
          itemStyle: { color: colorForGrade(g.id, g.color) },
        })),
      },
    ],
  };

  const inventoryAreaOption = {
    grid: chartGrid,
    tooltip: tooltipStyle,
    xAxis: { type: "category", data: dates.map((d) => d.slice(5)) },
    yAxis: {
      type: "value",
      axisLabel: { formatter: (v: number) => `${v.toLocaleString("en-CA")} L` },
      splitLine: { lineStyle: { color: "rgba(148,163,184,0.15)" } },
    },
    legend: { top: 4, textStyle: { color: "#94a3b8" } },
    series: grades.map((g) => ({
      name: g.label,
      type: "line",
      stack: "inv",
      smooth: true,
      areaStyle: { opacity: 0.32 },
      showSymbol: false,
      lineStyle: { width: 1.5 },
      itemStyle: { color: colorForGrade(g.id, g.color) },
      data: dailyMargins.map(
        (d) =>
          d.margin?.rows.find((r) => r.gradeId === g.id)?.eodInventoryL ?? null,
      ),
    })),
  };

  return (
    <div className="space-y-8">
      <header className="flex flex-wrap items-center justify-between gap-4">
        <div>
          <div className="text-sm text-muted-foreground">
            {new Date().toLocaleDateString("en-CA", {
              weekday: "long",
              year: "numeric",
              month: "long",
              day: "numeric",
            })}
          </div>
          <h1 className="text-3xl font-semibold tracking-tight">
            Good to see you, {user.displayName.split(" ")[0]}
          </h1>
          <p className="text-sm text-muted-foreground">
            Live operations dashboard for the past 30 days.
          </p>
        </div>
        <Badge variant={user.role === "admin" ? "default" : "secondary"} className="capitalize">
          {user.role}
        </Badge>
      </header>

      {loading ? (
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Loader2 className="h-4 w-4 animate-spin" /> Loading metrics…
        </div>
      ) : null}

      <section className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
        <Kpi
          icon={<Wallet className="h-4 w-4" />}
          label="Today's gross profit"
          value={formatCAD(todayGrossProfit)}
          sub={
            dayChange ? (
              <span
                className={
                  dayChange >= 0
                    ? "text-success flex items-center gap-1"
                    : "text-destructive flex items-center gap-1"
                }
              >
                {dayChange >= 0 ? (
                  <ArrowUpRight className="h-3 w-3" />
                ) : (
                  <ArrowDownRight className="h-3 w-3" />
                )}
                {Math.abs(dayChange).toFixed(1)}% vs yesterday
              </span>
            ) : (
              <span className="text-muted-foreground">no prior data</span>
            )
          }
        />
        <Kpi
          icon={<Droplets className="h-4 w-4" />}
          label="Today's volume sold"
          value={formatLiters(todayGallonsSold)}
          sub={<span className="text-muted-foreground">{formatCAD(todayFuelRevenue)} fuel revenue</span>}
        />
        <Kpi
          icon={<TrendingUp className="h-4 w-4" />}
          label="MTD weighted margin"
          value={formatPerLiter(rollingWeightedMargin)}
          sub={<span className="text-muted-foreground">{formatCAD(mtdGrossProfit)} MTD gross profit</span>}
        />
        <Kpi
          icon={<Fuel className="h-4 w-4" />}
          label="MTD volume"
          value={formatLiters(mtdLitersSold)}
          sub={<span className="text-muted-foreground">{grades.length} grades tracked</span>}
        />
      </section>

      <section className="grid gap-4 lg:grid-cols-3">
        <Card className="lg:col-span-2">
          <CardHeader>
            <CardTitle>Associate margin trend</CardTitle>
            <CardDescription>$/L margin per fuel grade -- last 30 days</CardDescription>
          </CardHeader>
          <CardContent>
            <EChart option={marginLineOption} height={300} />
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle>Volume mix</CardTitle>
            <CardDescription>Liters sold by grade (30d)</CardDescription>
          </CardHeader>
          <CardContent>
            <EChart option={fuelMixDonutOption} height={300} />
          </CardContent>
        </Card>
      </section>

      <section className="grid gap-4 lg:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle>Daily gross profit</CardTitle>
            <CardDescription>Total $ across all grades</CardDescription>
          </CardHeader>
          <CardContent>
            <EChart option={grossProfitBarOption} height={260} />
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle>Inventory by grade</CardTitle>
            <CardDescription>End-of-day inventory in liters (stacked)</CardDescription>
          </CardHeader>
          <CardContent>
            <EChart option={inventoryAreaOption} height={260} />
          </CardContent>
        </Card>
      </section>
    </div>
  );
}

function Kpi({
  icon,
  label,
  value,
  sub,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
  sub: React.ReactNode;
}) {
  return (
    <Card className="overflow-hidden">
      <CardContent className="space-y-2 p-5">
        <div className="flex items-center justify-between text-sm text-muted-foreground">
          <span>{label}</span>
          <span className="flex h-7 w-7 items-center justify-center rounded-md bg-secondary">
            {icon}
          </span>
        </div>
        <div className="number-tabular text-2xl font-semibold tracking-tight">{value}</div>
        <div className="text-xs">{sub}</div>
      </CardContent>
    </Card>
  );
}
