import { useEffect, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { Loader2, Plus, Save, Truck, X } from "lucide-react";

import { api } from "@/lib/api";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { useAuth } from "@/lib/auth-store";
import { isoDate, formatCAD } from "@/lib/utils";
import type {
  FuelDeliveriesFile,
  FuelDeliveryRecord,
  FuelGradesConfig,
  SalesFile,
  TaxConstants,
} from "@/lib/types";
import { recomputeAndSaveMargin } from "@/lib/derived";

export default function FuelDeliveryPage() {
  const user = useAuth((s) => s.user)!;
  const qc = useQueryClient();
  const today = isoDate();
  const [date, setDate] = useState(today);
  const [saving, setSaving] = useState(false);

  const gradesQ = useQuery({
    queryKey: ["config", "fuel_grades"],
    queryFn: () => api.readData<FuelGradesConfig>("config/fuel_grades.json"),
  });
  const taxesQ = useQuery({
    queryKey: ["config", "taxes"],
    queryFn: () => api.readData<TaxConstants>("config/taxes.json"),
  });
  const deliveryQ = useQuery({
    queryKey: ["delivery", date],
    queryFn: () => api.readData<FuelDeliveriesFile>(`fuel_deliveries/${date}.json`),
  });
  const salesQ = useQuery({
    queryKey: ["sales", date],
    queryFn: () => api.readData<SalesFile>(`sales/${date}.json`),
  });

  const grades = gradesQ.data?.data?.grades ?? [];

  const [file, setFile] = useState<FuelDeliveriesFile>(() => ({ date, entries: [] }));

  useEffect(() => {
    if (deliveryQ.data?.exists && deliveryQ.data.data) {
      setFile(deliveryQ.data.data);
    } else {
      setFile({ date, entries: [] });
    }
  }, [date, deliveryQ.data?.exists, deliveryQ.data?.data]);

  const update = (idx: number, patch: Partial<FuelDeliveryRecord>) =>
    setFile((f) => {
      const entries = [...f.entries];
      entries[idx] = { ...entries[idx], ...patch };
      return { ...f, entries };
    });

  const addEntry = () =>
    setFile((f) => ({
      ...f,
      entries: [
        ...f.entries,
        {
          id: crypto.randomUUID(),
          gradeId: grades[0]?.id ?? "",
          invoiceNo: "",
          purchaseVolumeL: 0,
          productCostExTaxPerL: 0,
          deliveryCostPerL: 0,
        },
      ],
    }));

  const removeEntry = (idx: number) =>
    setFile((f) => ({ ...f, entries: f.entries.filter((_, i) => i !== idx) }));

  async function handleSave() {
    if (!gradesQ.data?.data) return;
    setSaving(true);
    try {
      const payload: FuelDeliveriesFile = {
        ...file,
        date,
        entries: file.entries.map((e) => ({
          ...e,
          recordedBy: e.recordedBy ?? user.username,
          recordedAt: e.recordedAt ?? new Date().toISOString(),
        })),
      };
      const expected = deliveryQ.data?.sha ?? null;
      await api.writeData(
        `fuel_deliveries/${date}.json`,
        payload,
        expected,
        `fuel delivery for ${date}`,
      );
      toast.success("Delivery saved");

      const taxes = (taxesQ.data?.exists ? taxesQ.data.data : undefined) as TaxConstants | undefined;
      const sales = (salesQ.data?.exists ? salesQ.data.data : null) as SalesFile | null;
      await recomputeAndSaveMargin({
        date,
        gradesCfg: gradesQ.data.data,
        taxes: taxes ?? {
          fetPerL: 0,
          pftPerL: 0,
          carbonPerL: 0,
          urbanPerL: 0,
          rebatePerL: 0,
          gstPct: 0,
          pstPct: 0,
          hstPct: 0,
        },
        sales,
        delivery: payload,
      });
      qc.invalidateQueries({ queryKey: ["delivery"] });
      qc.invalidateQueries({ queryKey: ["margin"] });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to save");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="space-y-8">
      <header className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <Badge variant="secondary" className="mb-2">
            <Truck className="mr-1 h-3 w-3" /> Fuel delivery
          </Badge>
          <h1 className="text-3xl font-semibold tracking-tight">Record a fuel delivery</h1>
          <p className="text-sm text-muted-foreground">
            Add each invoice line. The rolling-average cost updates as soon as you save.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Label className="text-xs text-muted-foreground">Delivery date</Label>
          <Input
            type="date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            disabled={user.role !== "admin"}
            className="w-44"
          />
        </div>
      </header>

      <Card>
        <CardHeader className="flex flex-row items-center justify-between">
          <div>
            <CardTitle>Delivery lines</CardTitle>
            <CardDescription>
              Unit cost should EXCLUDE all taxes; delivery cost is converted to $/L.
            </CardDescription>
          </div>
          <Button onClick={addEntry} variant="outline">
            <Plus className="h-4 w-4" /> Add line
          </Button>
        </CardHeader>
        <CardContent className="space-y-4">
          {file.entries.length === 0 ? (
            <div className="rounded-md border border-dashed py-10 text-center text-sm text-muted-foreground">
              No delivery lines yet for {date}. Click <strong>Add line</strong> to start.
            </div>
          ) : (
            file.entries.map((e, i) => {
              const total = e.purchaseVolumeL * (e.productCostExTaxPerL + e.deliveryCostPerL);
              return (
                <div
                  key={e.id}
                  className="grid grid-cols-2 gap-3 rounded-md border bg-card/40 p-4 md:grid-cols-[1.2fr_1fr_1fr_1fr_1fr_auto] md:items-end"
                >
                  <div className="space-y-1.5">
                    <Label className="text-xs text-muted-foreground">Grade</Label>
                    <Select
                      value={e.gradeId}
                      onValueChange={(v) => update(i, { gradeId: v })}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Grade" />
                      </SelectTrigger>
                      <SelectContent>
                        {grades.map((g) => (
                          <SelectItem key={g.id} value={g.id}>
                            {g.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs text-muted-foreground">Invoice #</Label>
                    <Input
                      value={e.invoiceNo}
                      onChange={(ev) => update(i, { invoiceNo: ev.target.value })}
                      placeholder="INV-0001"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs text-muted-foreground">Volume (L)</Label>
                    <Input
                      type="number"
                      step="0.01"
                      inputMode="decimal"
                      value={e.purchaseVolumeL || ""}
                      onChange={(ev) =>
                        update(i, { purchaseVolumeL: parseFloat(ev.target.value) || 0 })
                      }
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs text-muted-foreground">Unit cost $/L (ex-tax)</Label>
                    <Input
                      type="number"
                      step="0.0001"
                      inputMode="decimal"
                      value={e.productCostExTaxPerL || ""}
                      onChange={(ev) =>
                        update(i, { productCostExTaxPerL: parseFloat(ev.target.value) || 0 })
                      }
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs text-muted-foreground">Delivery $/L</Label>
                    <Input
                      type="number"
                      step="0.0001"
                      inputMode="decimal"
                      value={e.deliveryCostPerL || ""}
                      onChange={(ev) =>
                        update(i, { deliveryCostPerL: parseFloat(ev.target.value) || 0 })
                      }
                    />
                  </div>
                  <div className="flex flex-col items-end gap-2 md:items-stretch">
                    <div className="text-right text-xs uppercase text-muted-foreground">
                      Line total
                    </div>
                    <div className="text-right text-sm font-semibold number-tabular">
                      {formatCAD(total)}
                    </div>
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => removeEntry(i)}
                      aria-label="Remove line"
                    >
                      <X className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              );
            })
          )}
        </CardContent>
      </Card>

      <div className="flex justify-end">
        <Button size="lg" disabled={saving || file.entries.length === 0} onClick={handleSave}>
          {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
          Save delivery
        </Button>
      </div>
    </div>
  );
}
